/**
 * Workflow run CLI commands
 *
 * Implements workflow run lifecycle management:
 * - kspec workflow start @ref [--task @ref] [--json]
 * - kspec workflow runs [--active] [--completed] [--workflow @ref] [--json]
 * - kspec workflow show @run [--json]
 * - kspec workflow abort @run [--reason text] [--json]
 */

import chalk from "chalk";
import Table from "cli-table3";
import type { Command } from "commander";
import { ulid } from "ulid";
import {
  findActiveRuns,
  findWorkflowRunByRef,
  getAuthor,
  initContext,
  loadAllTasks,
  loadMetaContext,
  loadWorkflowRuns,
  ReferenceIndex,
  saveWorkflowRun,
  updateWorkflowRun,
  type Workflow,
} from "../../parser/index.js";
import { commitIfShadow } from "../../parser/shadow.js";
import type { WorkflowRun } from "../../schema/index.js";
import { errors } from "../../strings/errors.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, isJsonMode, output, success } from "../output.js";

/**
 * Find a workflow by reference
 */
function resolveWorkflowRef(
  ref: string,
  workflows: Workflow[],
): Workflow | null {
  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;

  // Try by ID first
  let workflow = workflows.find((w) => w.id === cleanRef);
  if (workflow) return workflow;

  // Try by ULID or ULID prefix
  workflow = workflows.find(
    (w) =>
      w._ulid === cleanRef ||
      w._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()),
  );
  return workflow || null;
}

/**
 * Format a short ULID (first 8 chars)
 */
function shortUlid(ulid: string): string {
  return ulid.slice(0, 8).toUpperCase();
}

/**
 * Format run status with color
 */
function formatStatus(status: string): string {
  switch (status) {
    case "active":
      return chalk.green(status);
    case "paused":
      return chalk.yellow(status);
    case "completed":
      return chalk.blue(status);
    case "aborted":
      return chalk.red(status);
    default:
      return status;
  }
}

/**
 * Command: kspec workflow start @workflow-ref [--task @task-ref] [--json]
 * AC: @workflow-run-foundation ac-1, ac-6
 */
async function workflowStart(
  workflowRef: string,
  options: { task?: string; json?: boolean },
) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);

  // DEBUG: Log loaded workflows
  // Resolve workflow reference
  const workflow = resolveWorkflowRef(workflowRef, metaCtx.workflows);
  if (!workflow) {
    error(errors.workflowRun.workflowNotFound(workflowRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // Validate task reference if provided (AC: @workflow-run-foundation ac-6)
  let taskRef: string | undefined;
  if (options.task) {
    const tasks = await loadAllTasks(ctx);
    const index = new ReferenceIndex(tasks, []);
    const result = index.resolve(options.task);
    if (!result.ok) {
      error(errors.reference.taskNotFound(options.task));
      process.exit(EXIT_CODES.NOT_FOUND);
    }
    taskRef = `@${result.ulid}`;
  }

  // Create new workflow run
  const run: WorkflowRun = {
    _ulid: ulid(),
    workflow_ref: `@${workflow._ulid}`,
    status: "active",
    current_step: 0,
    total_steps: workflow.steps.length,
    started_at: new Date().toISOString(),
    step_results: [],
    initiated_by: getAuthor(),
    task_ref: taskRef,
  };

  // Save the run
  await saveWorkflowRun(ctx, run);

  // Commit to shadow
  await commitIfShadow(ctx.shadow, "workflow-start");

  // Output result
  if (isJsonMode()) {
    output({
      run_id: run._ulid,
      workflow_ref: run.workflow_ref,
      status: run.status,
    });
  } else {
    success(`Started workflow run: ${shortUlid(run._ulid)}`);
    console.log(`  Workflow: ${workflow.id}`);
    console.log(`  Steps: ${run.total_steps}`);
    if (taskRef) {
      console.log(`  Linked task: ${taskRef}`);
    }
  }
}

/**
 * Command: kspec workflow runs [--active] [--completed] [--workflow @ref] [--json]
 * AC: @workflow-run-foundation ac-2
 */
async function workflowRuns(options: {
  active?: boolean;
  completed?: boolean;
  workflow?: string;
  json?: boolean;
}) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);
  let runs = await loadWorkflowRuns(ctx);

  // Apply filters
  if (options.active) {
    runs = runs.filter((r) => r.status === "active");
  }
  if (options.completed) {
    runs = runs.filter((r) => r.status === "completed");
  }
  if (options.workflow) {
    const workflow = resolveWorkflowRef(options.workflow, metaCtx.workflows);
    if (!workflow) {
      error(errors.workflowRun.workflowNotFound(options.workflow));
      process.exit(EXIT_CODES.NOT_FOUND);
    }
    runs = runs.filter((r) => r.workflow_ref === `@${workflow._ulid}`);
  }

  if (isJsonMode()) {
    output({ runs });
  } else {
    if (runs.length === 0) {
      console.log(chalk.gray("No workflow runs found"));
      return;
    }

    const table = new Table({
      head: ["ID", "Workflow", "Status", "Step", "Started"],
      colWidths: [12, 25, 12, 10, 20],
    });

    for (const run of runs) {
      const workflow = metaCtx.workflows.find(
        (w) => `@${w._ulid}` === run.workflow_ref,
      );
      const workflowName = workflow?.id || run.workflow_ref;
      const stepProgress = `${run.current_step}/${run.total_steps}`;
      const started = new Date(run.started_at).toLocaleString();

      table.push([
        shortUlid(run._ulid),
        workflowName,
        formatStatus(run.status),
        stepProgress,
        started,
      ]);
    }

    console.log(table.toString());
  }
}

/**
 * Command: kspec workflow show @run-id [--json]
 * AC: @workflow-run-foundation ac-4
 */
async function workflowShow(runRef: string, _options: { json?: boolean }) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);

  const run = await findWorkflowRunByRef(ctx, runRef);
  if (!run) {
    error(errors.workflowRun.runNotFound(runRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  if (isJsonMode()) {
    output({ run });
  } else {
    const workflow = metaCtx.workflows.find(
      (w) => `@${w._ulid}` === run.workflow_ref,
    );
    const workflowName = workflow?.id || run.workflow_ref;

    console.log(chalk.bold("Workflow Run Details"));
    console.log(chalk.gray("─".repeat(50)));
    console.log(`ID:           ${shortUlid(run._ulid)}`);
    console.log(`Workflow:     ${workflowName} (${run.workflow_ref})`);
    console.log(`Status:       ${formatStatus(run.status)}`);
    console.log(`Progress:     ${run.current_step}/${run.total_steps}`);
    console.log(`Started:      ${new Date(run.started_at).toLocaleString()}`);

    if (run.initiated_by) {
      console.log(`Initiated by: ${run.initiated_by}`);
    }
    if (run.task_ref) {
      console.log(`Task:         ${run.task_ref}`);
    }
    if (run.paused_at) {
      console.log(`Paused:       ${new Date(run.paused_at).toLocaleString()}`);
    }
    if (run.completed_at) {
      console.log(
        `Completed:    ${new Date(run.completed_at).toLocaleString()}`,
      );
    }
    if (run.abort_reason) {
      console.log(`Abort reason: ${run.abort_reason}`);
    }

    if (run.step_results.length > 0) {
      console.log(chalk.gray("\nStep Results:"));
      const table = new Table({
        head: ["Step", "Status", "Started", "Completed"],
        colWidths: [8, 12, 20, 20],
      });

      for (const result of run.step_results) {
        table.push([
          result.step_index.toString(),
          formatStatus(result.status),
          new Date(result.started_at).toLocaleString(),
          new Date(result.completed_at).toLocaleString(),
        ]);
      }

      console.log(table.toString());
    }
  }
}

/**
 * Command: kspec workflow abort @run-id [--reason text] [--json]
 * AC: @workflow-run-foundation ac-3, ac-5
 */
async function workflowAbort(
  runRef: string,
  options: { reason?: string; json?: boolean },
) {
  const ctx = await initContext();

  const run = await findWorkflowRunByRef(ctx, runRef);
  if (!run) {
    error(errors.workflowRun.runNotFound(runRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // AC: @workflow-run-foundation ac-5 - Cannot abort completed or aborted runs
  if (run.status === "completed") {
    error(errors.workflowRun.cannotAbortCompleted);
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  if (run.status === "aborted") {
    error(errors.workflowRun.cannotAbortAborted);
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  // Update run status
  run.status = "aborted";
  run.abort_reason = options.reason;
  run.completed_at = new Date().toISOString();

  await updateWorkflowRun(ctx, run);
  await commitIfShadow(ctx.shadow, "workflow-abort");

  if (isJsonMode()) {
    output({ run_id: run._ulid, status: run.status });
  } else {
    success(`Aborted workflow run: ${shortUlid(run._ulid)}`);
    if (options.reason) {
      console.log(`  Reason: ${options.reason}`);
    }
  }
}

/**
 * Command: kspec workflow pause @run-id [--json]
 * AC: @workflow-advanced-features ac-1
 */
async function workflowPause(runRef: string, _options: { json?: boolean }) {
  const ctx = await initContext();

  const run = await findWorkflowRunByRef(ctx, runRef);
  if (!run) {
    error(errors.workflowRun.runNotFound(runRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // Only active runs can be paused
  if (run.status !== "active") {
    error(
      `Cannot pause run ${shortUlid(run._ulid)}: current status is ${run.status}`,
    );
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  // Update run status
  run.status = "paused";
  run.paused_at = new Date().toISOString();

  await updateWorkflowRun(ctx, run);
  await commitIfShadow(ctx.shadow, "workflow-pause");

  if (isJsonMode()) {
    output({ run_id: run._ulid, status: run.status, paused_at: run.paused_at });
  } else {
    success(
      `Paused run ${shortUlid(run._ulid)} at step ${run.current_step + 1}/${run.total_steps}`,
    );
  }
}

/**
 * Command: kspec workflow resume @run-id [--json]
 * AC: @workflow-advanced-features ac-2, ac-4
 */
async function workflowResume(runRef: string, _options: { json?: boolean }) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);

  const run = await findWorkflowRunByRef(ctx, runRef);
  if (!run) {
    error(errors.workflowRun.runNotFound(runRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // AC: @workflow-advanced-features ac-4 - Error if not paused
  if (run.status !== "paused") {
    error(
      `Cannot resume run ${shortUlid(run._ulid)}: current status is ${run.status} (expected paused)`,
    );
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  // Update run status
  run.status = "active";
  run.paused_at = undefined;

  await updateWorkflowRun(ctx, run);
  await commitIfShadow(ctx.shadow, "workflow-resume");

  // Get workflow definition to show current step
  const workflow = metaCtx.workflows.find(
    (w) => `@${w._ulid}` === run.workflow_ref,
  );
  if (!workflow) {
    error(errors.workflowRun.workflowNotFound(run.workflow_ref));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  const currentStep = workflow.steps[run.current_step];

  if (isJsonMode()) {
    output({
      run_id: run._ulid,
      status: run.status,
      current_step: run.current_step,
      total_steps: run.total_steps,
      next_step: {
        type: currentStep.type,
        content: currentStep.content,
      },
    });
  } else {
    success(`Resumed run ${shortUlid(run._ulid)}`);
    console.log(
      `\nStep ${run.current_step + 1}/${run.total_steps}: [${currentStep.type}] ${currentStep.content}`,
    );
  }
}

/**
 * Command: kspec workflow next [run-ref] [--skip] [--notes text] [--confirm] [--force] [--input key=value] [--json]
 * AC: @workflow-step-navigation ac-1 through ac-6
 * AC: @workflow-enforcement-modes ac-1 through ac-4
 * AC: @workflow-advanced-features ac-3
 */
async function workflowNext(
  runRef: string | undefined,
  options: {
    skip?: boolean;
    notes?: string;
    confirm?: boolean;
    force?: boolean;
    input?: string[];
    json?: boolean;
  },
) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);

  let run: WorkflowRun | undefined;

  // AC: @workflow-step-navigation ac-3, ac-4, ac-5
  if (!runRef) {
    const activeRuns = await findActiveRuns(ctx);

    if (activeRuns.length === 0) {
      // AC: @workflow-step-navigation ac-5
      error(errors.workflowRun.noActiveRuns);
      process.exit(EXIT_CODES.NOT_FOUND);
    }

    if (activeRuns.length > 1) {
      // AC: @workflow-step-navigation ac-4
      const runIds = activeRuns.map((r) => shortUlid(r._ulid));
      error(errors.workflowRun.multipleActiveRuns(runIds));
      process.exit(EXIT_CODES.VALIDATION_FAILED);
    }

    // AC: @workflow-step-navigation ac-3 - exactly one active run
    run = activeRuns[0];
  } else {
    run = await findWorkflowRunByRef(ctx, runRef);
    if (!run) {
      error(errors.workflowRun.runNotFound(runRef));
      process.exit(EXIT_CODES.NOT_FOUND);
    }

    if (run.status !== "active") {
      error(errors.workflowRun.runNotActive(runRef, run.status));
      process.exit(EXIT_CODES.VALIDATION_FAILED);
    }
  }

  // Get workflow definition to access steps
  const workflow = metaCtx.workflows.find(
    (w) => `@${w._ulid}` === run.workflow_ref,
  );
  if (!workflow) {
    error(errors.workflowRun.workflowNotFound(run.workflow_ref));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // Get current step and next step
  const currentStepIndex = run.current_step;
  const currentStep = workflow.steps[currentStepIndex];
  const isStrictMode = workflow.enforcement === "strict";
  const isLastStep = currentStepIndex === run.total_steps - 1;

  // AC: @workflow-advanced-features ac-3 - Handle step inputs
  const stepInputs: Record<string, string> = {};
  if (currentStep.inputs && currentStep.inputs.length > 0) {
    // Display required inputs if not in JSON mode
    if (!isJsonMode()) {
      console.log(
        `Step ${currentStepIndex + 1}/${run.total_steps}: [${currentStep.type}] ${currentStep.content}`,
      );
      console.log(chalk.cyan("  Inputs required:"));
      for (const input of currentStep.inputs) {
        const requiredLabel = input.required !== false ? "" : " (optional)";
        const typeLabel = input.type ? ` (${input.type})` : "";
        const desc = input.description ? `: ${input.description}` : "";
        console.log(
          chalk.cyan(`    - ${input.name}${typeLabel}${requiredLabel}${desc}`),
        );
      }
      console.log();
    }

    // Parse --input flags
    if (options.input) {
      for (const inputStr of options.input) {
        const [key, ...valueParts] = inputStr.split("=");
        if (!valueParts.length) {
          error(
            `Invalid input format: "${inputStr}". Expected format: key=value`,
          );
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        }
        stepInputs[key] = valueParts.join("="); // Rejoin in case value contains '='
      }
    }

    // Validate required inputs
    for (const input of currentStep.inputs) {
      if (input.required !== false && !stepInputs[input.name]) {
        error(`Missing required input: ${input.name}`);
        process.exit(EXIT_CODES.VALIDATION_FAILED);
      }
    }
  }

  // AC: @workflow-enforcement-modes ac-3 - Strict mode: --skip requires --force
  if (options.skip && isStrictMode && !options.force) {
    error(errors.workflowRun.skipRequiresForce);
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  // AC: @workflow-enforcement-modes ac-2, ac-3 - Check exit criteria for CURRENT step
  if (
    currentStep.exit_criteria &&
    currentStep.exit_criteria.length > 0 &&
    !options.skip
  ) {
    // AC: @workflow-enforcement-modes ac-3 - Strict mode requires --confirm
    if (isStrictMode && !options.confirm) {
      if (!isJsonMode()) {
        console.log(
          `Completing step ${currentStepIndex + 1}/${run.total_steps}: [${currentStep.type}] ${currentStep.content}`,
        );
        console.log(chalk.yellow("  Exit criteria:"));
        for (const criterion of currentStep.exit_criteria) {
          console.log(chalk.yellow(`    - ${criterion}`));
        }
        console.log();
      }
      error(errors.workflowRun.exitCriteriaNotConfirmed);
      process.exit(EXIT_CODES.VALIDATION_FAILED);
    }

    // AC: @workflow-enforcement-modes ac-4 - Advisory mode shows criteria as guidance
    if (!isStrictMode && !isJsonMode()) {
      console.log(chalk.gray("  Exit criteria:"));
      for (const criterion of currentStep.exit_criteria) {
        console.log(chalk.gray(`    - ${criterion}`));
      }
    }
  }

  // AC: @workflow-enforcement-modes ac-1, ac-3 - Check entry criteria for NEXT step
  // (Only applies when advancing from current step normally, not when skipping or completing the workflow)
  // When skipping, we don't check entry criteria because we're not actually starting the next step yet
  if (!isLastStep && !options.skip) {
    const nextStep = workflow.steps[currentStepIndex + 1];
    if (nextStep.entry_criteria && nextStep.entry_criteria.length > 0) {
      // AC: @workflow-enforcement-modes ac-3 - Strict mode requires --confirm
      if (isStrictMode && !options.confirm) {
        if (!isJsonMode()) {
          console.log(
            `Step ${currentStepIndex + 2}/${run.total_steps}: [${nextStep.type}] ${nextStep.content}`,
          );
          console.log(chalk.yellow("  Entry criteria:"));
          for (const criterion of nextStep.entry_criteria) {
            console.log(chalk.yellow(`    - ${criterion}`));
          }
          console.log();
        }
        error(errors.workflowRun.entryCriteriaNotConfirmed);
        process.exit(EXIT_CODES.VALIDATION_FAILED);
      }

      // AC: @workflow-enforcement-modes ac-4 - Advisory mode shows criteria as guidance
      if (!isStrictMode && !isJsonMode()) {
        console.log(
          `Step ${currentStepIndex + 2}/${run.total_steps}: [${nextStep.type}] ${nextStep.content}`,
        );
        console.log(chalk.gray("  Entry criteria:"));
        for (const criterion of nextStep.entry_criteria) {
          console.log(chalk.gray(`    - ${criterion}`));
        }
        console.log();
      }
    }
  }

  // AC: @workflow-step-navigation ac-1, ac-6 - Complete current step
  const previousResult = run.step_results[run.step_results.length - 1];
  const startedAt = previousResult
    ? previousResult.completed_at
    : run.started_at;

  // AC: @workflow-enforcement-modes ac-3 - Record confirmations in StepResult
  // Check if a stub result already exists for this step (created when we advanced to it)
  const existingResultIndex = run.step_results.findIndex(
    (r) => r.step_index === currentStepIndex,
  );

  if (existingResultIndex >= 0) {
    // Update existing stub result with completion data
    const existingResult = run.step_results[existingResultIndex];
    run.step_results[existingResultIndex] = {
      ...existingResult,
      status: options.skip ? ("skipped" as const) : ("completed" as const),
      completed_at: new Date().toISOString(),
      notes: options.notes,
      exit_confirmed:
        currentStep.exit_criteria &&
        currentStep.exit_criteria.length > 0 &&
        options.confirm
          ? true
          : undefined,
      inputs: Object.keys(stepInputs).length > 0 ? stepInputs : undefined,
    };
  } else {
    // No stub exists (first step or old data), create complete result
    const stepResult = {
      step_index: currentStepIndex,
      status: options.skip ? ("skipped" as const) : ("completed" as const),
      started_at: startedAt,
      completed_at: new Date().toISOString(),
      notes: options.notes,
      exit_confirmed:
        currentStep.exit_criteria &&
        currentStep.exit_criteria.length > 0 &&
        options.confirm
          ? true
          : undefined,
      entry_confirmed: undefined,
      inputs: Object.keys(stepInputs).length > 0 ? stepInputs : undefined,
    };
    run.step_results.push(stepResult);
  }

  // AC: @workflow-step-navigation ac-1 - Advance to next step or complete run
  if (isLastStep) {
    // AC: @workflow-step-navigation ac-2 - Complete the run
    run.status = "completed";
    run.completed_at = new Date().toISOString();

    await updateWorkflowRun(ctx, run);
    await commitIfShadow(ctx.shadow, "workflow-next");

    // Calculate summary stats
    const totalDuration =
      new Date(run.completed_at).getTime() - new Date(run.started_at).getTime();
    const completedSteps = run.step_results.filter(
      (r) => r.status === "completed",
    ).length;
    const skippedSteps = run.step_results.filter(
      (r) => r.status === "skipped",
    ).length;

    if (isJsonMode()) {
      output({
        run_id: run._ulid,
        status: run.status,
        completed_at: run.completed_at,
        total_duration_ms: totalDuration,
        steps_completed: completedSteps,
        steps_skipped: skippedSteps,
      });
    } else {
      const currentStep = workflow.steps[currentStepIndex];
      success(
        `Completed step ${currentStepIndex + 1}/${run.total_steps}: [${currentStep.type}] ${currentStep.content}`,
      );
      console.log();
      console.log(chalk.bold("Workflow completed!"));
      console.log(`  Duration: ${Math.round(totalDuration / 1000)}s`);
      console.log(`  Steps completed: ${completedSteps}`);
      console.log(`  Steps skipped: ${skippedSteps}`);
    }
  } else {
    // Advance to next step
    run.current_step += 1;

    // AC: @workflow-enforcement-modes ac-3 - Record entry confirmation for the next step
    // Create a stub step result for the next step to capture entry_confirmed and started_at
    // This will be updated with completion data when the step is completed
    const nextStep = workflow.steps[run.current_step];
    const nextStepStartedAt =
      run.step_results[run.step_results.length - 1]?.completed_at ||
      new Date().toISOString();
    const nextStepStub = {
      step_index: run.current_step,
      status: "completed" as const, // Placeholder, will be updated
      started_at: nextStepStartedAt,
      completed_at: nextStepStartedAt, // Placeholder, will be updated
      entry_confirmed:
        nextStep.entry_criteria &&
        nextStep.entry_criteria.length > 0 &&
        options.confirm
          ? true
          : undefined,
    };
    run.step_results.push(nextStepStub);

    await updateWorkflowRun(ctx, run);
    await commitIfShadow(ctx.shadow, "workflow-next");

    if (isJsonMode()) {
      output({
        run_id: run._ulid,
        current_step: run.current_step,
        total_steps: run.total_steps,
        next_step: {
          type: nextStep.type,
          content: nextStep.content,
        },
      });
    } else {
      const previousStep = workflow.steps[currentStepIndex];
      success(
        `Completed step ${currentStepIndex + 1}/${run.total_steps}: [${previousStep.type}] ${previousStep.content}`,
      );
      console.log();
      console.log(
        `Step ${run.current_step + 1}/${run.total_steps}: [${nextStep.type}] ${nextStep.content}`,
      );
    }
  }
}

/**
 * Register workflow commands
 */
export function registerWorkflowCommand(program: Command): void {
  const workflow = program
    .command("workflow")
    .description("Manage workflow runs");

  workflow
    .command("start")
    .description("Start a new workflow run")
    .argument("<workflow-ref>", "Workflow reference (@id or @ulid)")
    .option("--task <task-ref>", "Link run to a task")
    .option("--json", "Output JSON")
    .action(workflowStart);

  workflow
    .command("runs")
    .description("List workflow runs")
    .option("--active", "Show only active runs")
    .option("--completed", "Show only completed runs")
    .option("--workflow <ref>", "Filter by workflow")
    .option("--json", "Output JSON")
    .action(workflowRuns);

  workflow
    .command("show")
    .description("Show workflow run details")
    .argument("<run-ref>", "Run reference (@ulid or ulid prefix)")
    .option("--json", "Output JSON")
    .action(workflowShow);

  workflow
    .command("abort")
    .description("Abort an active workflow run")
    .argument("<run-ref>", "Run reference (@ulid or ulid prefix)")
    .option("--reason <text>", "Reason for aborting")
    .option("--json", "Output JSON")
    .action(workflowAbort);

  workflow
    .command("next")
    .description("Advance workflow run to next step")
    .argument("[run-ref]", "Run reference (optional if only one active run)")
    .option("--skip", "Mark current step as skipped")
    .option("--notes <text>", "Notes for the completed step")
    .option(
      "--confirm",
      "Acknowledge entry/exit criteria (required in strict mode)",
    )
    .option("--force", "Allow --skip in strict mode")
    .option(
      "--input <key=value>",
      "Provide step input (repeatable)",
      (value, previous: string[] = []) => [...previous, value],
    )
    .option("--json", "Output JSON")
    .action(workflowNext);

  workflow
    .command("pause")
    .description("Pause an active workflow run")
    .argument("<run-ref>", "Run reference (@ulid or ulid prefix)")
    .option("--json", "Output JSON")
    .action(workflowPause);

  workflow
    .command("resume")
    .description("Resume a paused workflow run")
    .argument("<run-ref>", "Run reference (@ulid or ulid prefix)")
    .option("--json", "Output JSON")
    .action(workflowResume);
}

update.rawOutput:
     1→/**
     2→ * Workflow run CLI commands
     3→ *
     4→ * Implements workflow run lifecycle management:
     5→ * - kspec workflow start @ref [--task @ref] [--json]
     6→ * - kspec workflow runs [--active] [--completed] [--workflow @ref] [--json]
     7→ * - kspec workflow show @run [--json]
     8→ * - kspec workflow abort @run [--reason text] [--json]
     9→ */
    10→
    11→import chalk from "chalk";
    12→import Table from "cli-table3";
    13→import type { Command } from "commander";
    14→import { ulid } from "ulid";
    15→import {
    16→  findActiveRuns,
    17→  findWorkflowRunByRef,
    18→  getAuthor,
    19→  initContext,
    20→  loadAllTasks,
    21→  loadMetaContext,
    22→  loadWorkflowRuns,
    23→  ReferenceIndex,
    24→  saveWorkflowRun,
    25→  updateWorkflowRun,
    26→  type Workflow,
    27→} from "../../parser/index.js";
    28→import { commitIfShadow } from "../../parser/shadow.js";
    29→import type { WorkflowRun } from "../../schema/index.js";
    30→import { errors } from "../../strings/errors.js";
    31→import { EXIT_CODES } from "../exit-codes.js";
    32→import { error, isJsonMode, output, success } from "../output.js";
    33→
    34→/**
    35→ * Find a workflow by reference
    36→ */
    37→function resolveWorkflowRef(
    38→  ref: string,
    39→  workflows: Workflow[],
    40→): Workflow | null {
    41→  const cleanRef = ref.startsWith("@") ? ref.slice(1) : ref;
    42→
    43→  // Try by ID first
    44→  let workflow = workflows.find((w) => w.id === cleanRef);
    45→  if (workflow) return workflow;
    46→
    47→  // Try by ULID or ULID prefix
    48→  workflow = workflows.find(
    49→    (w) =>
    50→      w._ulid === cleanRef ||
    51→      w._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()),
    52→  );
    53→  return workflow || null;
    54→}
    55→
    56→/**
    57→ * Format a short ULID (first 8 chars)
    58→ */
    59→function shortUlid(ulid: string): string {
    60→  return ulid.slice(0, 8).toUpperCase();
    61→}
    62→
    63→/**
    64→ * Format run status with color
    65→ */
    66→function formatStatus(status: string): string {
    67→  switch (status) {
    68→    case "active":
    69→      return chalk.green(status);
    70→    case "paused":
    71→      return chalk.yellow(status);
    72→    case "completed":
    73→      return chalk.blue(status);
    74→    case "aborted":
    75→      return chalk.red(status);
    76→    default:
    77→      return status;
    78→  }
    79→}
    80→
    81→/**
    82→ * Command: kspec workflow start @workflow-ref [--task @task-ref] [--json]
    83→ * AC: @workflow-run-foundation ac-1, ac-6
    84→ */
    85→async function workflowStart(
    86→  workflowRef: string,
    87→  options: { task?: string; json?: boolean },
    88→) {
    89→  const ctx = await initContext();
    90→  const metaCtx = await loadMetaContext(ctx);
    91→
    92→  // DEBUG: Log loaded workflows
    93→  // Resolve workflow reference
    94→  const workflow = resolveWorkflowRef(workflowRef, metaCtx.workflows);
    95→  if (!workflow) {
    96→    error(errors.workflowRun.workflowNotFound(workflowRef));
    97→    process.exit(EXIT_CODES.NOT_FOUND);
    98→  }
    99→
   100→  // Validate task reference if provided (AC: @workflow-run-foundation ac-6)
   101→  let taskRef: string | undefined;
   102→  if (options.task) {
   103→    const tasks = await loadAllTasks(ctx);
   104→    const index = new ReferenceIndex(tasks, []);
   105→    const result = index.resolve(options.task);
   106→    if (!result.ok) {
   107→      error(errors.reference.taskNotFound(options.task));
   108→      process.exit(EXIT_CODES.NOT_FOUND);
   109→    }
   110→    taskRef = `@${result.ulid}`;
   111→  }
   112→
   113→  // Create new workflow run
   114→  const run: WorkflowRun = {
   115→    _ulid: ulid(),
   116→    workflow_ref: `@${workflow._ulid}`,
   117→    status: "active",
   118→    current_step: 0,
   119→    total_steps: workflow.steps.length,
   120→    started_at: new Date().toISOString(),
   121→    step_results: [],
   122→    initiated_by: getAuthor(),
   123→    task_ref: taskRef,
   124→  };
   125→
   126→  // Save the run
   127→  await saveWorkflowRun(ctx, run);
   128→
   129→  // Commit to shadow
   130→  await commitIfShadow(ctx.shadow, "workflow-start");
   131→
   132→  // Output result
   133→  if (isJsonMode()) {
   134→    output({
   135→      run_id: run._ulid,
   136→      workflow_ref: run.workflow_ref,
   137→      status: run.status,
   138→    });
   139→  } else {
   140→    success(`Started workflow run: ${shortUlid(run._ulid)}`);
   141→    console.log(`  Workflow: ${workflow.id}`);
   142→    console.log(`  Steps: ${run.total_steps}`);
   143→    if (taskRef) {
   144→      console.log(`  Linked task: ${taskRef}`);
   145→    }
   146→  }
   147→}
   148→
   149→/**
   150→ * Command: kspec workflow runs [--active] [--completed] [--workflow @ref] [--json]
   151→ * AC: @workflow-run-foundation ac-2
   152→ */
   153→async function workflowRuns(options: {
   154→  active?: boolean;
   155→  completed?: boolean;
   156→  workflow?: string;
   157→  json?: boolean;
   158→}) {
   159→  const ctx = await initContext();
   160→  const metaCtx = await loadMetaContext(ctx);
   161→  let runs = await loadWorkflowRuns(ctx);
   162→
   163→  // Apply filters
   164→  if (options.active) {
   165→    runs = runs.filter((r) => r.status === "active");
   166→  }
   167→  if (options.completed) {
   168→    runs = runs.filter((r) => r.status === "completed");
   169→  }
   170→  if (options.workflow) {
   171→    const workflow = resolveWorkflowRef(options.workflow, metaCtx.workflows);
   172→    if (!workflow) {
   173→      error(errors.workflowRun.workflowNotFound(options.workflow));
   174→      process.exit(EXIT_CODES.NOT_FOUND);
   175→    }
   176→    runs = runs.filter((r) => r.workflow_ref === `@${workflow._ulid}`);
   177→  }
   178→
   179→  if (isJsonMode()) {
   180→    output({ runs });
   181→  } else {
   182→    if (runs.length === 0) {
   183→      console.log(chalk.gray("No workflow runs found"));
   184→      return;
   185→    }
   186→
   187→    const table = new Table({
   188→      head: ["ID", "Workflow", "Status", "Step", "Started"],
   189→      colWidths: [12, 25, 12, 10, 20],
   190→    });
   191→
   192→    for (const run of runs) {
   193→      const workflow = metaCtx.workflows.find(
   194→        (w) => `@${w._ulid}` === run.workflow_ref,
   195→      );
   196→      const workflowName = workflow?.id || run.workflow_ref;
   197→      const stepProgress = `${run.current_step}/${run.total_steps}`;
   198→      const started = new Date(run.started_at).toLocaleString();
   199→
   200→      table.push([
   201→        shortUlid(run._ulid),
   202→        workflowName,
   203→        formatStatus(run.status),
   204→        stepProgress,
   205→        started,
   206→      ]);
   207→    }
   208→
   209→    console.log(table.toString());
   210→  }
   211→}
   212→
   213→/**
   214→ * Command: kspec workflow show @run-id [--json]
   215→ * AC: @workflow-run-foundation ac-4
   216→ */
   217→async function workflowShow(runRef: string, _options: { json?: boolean }) {
   218→  const ctx = await initContext();
   219→  const metaCtx = await loadMetaContext(ctx);
   220→
   221→  const run = await findWorkflowRunByRef(ctx, runRef);
   222→  if (!run) {
   223→    error(errors.workflowRun.runNotFound(runRef));
   224→    process.exit(EXIT_CODES.NOT_FOUND);
   225→  }
   226→
   227→  if (isJsonMode()) {
   228→    output({ run });
   229→  } else {
   230→    const workflow = metaCtx.workflows.find(
   231→      (w) => `@${w._ulid}` === run.workflow_ref,
   232→    );
   233→    const workflowName = workflow?.id || run.workflow_ref;
   234→
   235→    console.log(chalk.bold("Workflow Run Details"));
   236→    console.log(chalk.gray("─".repeat(50)));
   237→    console.log(`ID:           ${shortUlid(run._ulid)}`);
   238→    console.log(`Workflow:     ${workflowName} (${run.workflow_ref})`);
   239→    console.log(`Status:       ${formatStatus(run.status)}`);
   240→    console.log(`Progress:     ${run.current_step}/${run.total_steps}`);
   241→    console.log(`Started:      ${new Date(run.started_at).toLocaleString()}`);
   242→
   243→    if (run.initiated_by) {
   244→      console.log(`Initiated by: ${run.initiated_by}`);
   245→    }
   246→    if (run.task_ref) {
   247→      console.log(`Task:         ${run.task_ref}`);
   248→    }
   249→    if (run.paused_at) {
   250→      console.log(`Paused:       ${new Date(run.paused_at).toLocaleString()}`);
   251→    }
   252→    if (run.completed_at) {
   253→      console.log(
   254→        `Completed:    ${new Date(run.completed_at).toLocaleString()}`,
   255→      );
   256→    }
   257→    if (run.abort_reason) {
   258→      console.log(`Abort reason: ${run.abort_reason}`);
   259→    }
   260→
   261→    if (run.step_results.length > 0) {
   262→      console.log(chalk.gray("\nStep Results:"));
   263→      const table = new Table({
   264→        head: ["Step", "Status", "Started", "Completed"],
   265→        colWidths: [8, 12, 20, 20],
   266→      });
   267→
   268→      for (const result of run.step_results) {
   269→        table.push([
   270→          result.step_index.toString(),
   271→          formatStatus(result.status),
   272→          new Date(result.started_at).toLocaleString(),
   273→          new Date(result.completed_at).toLocaleString(),
   274→        ]);
   275→      }
   276→
   277→      console.log(table.toString());
   278→    }
   279→  }
   280→}
   281→
   282→/**
   283→ * Command: kspec workflow abort @run-id [--reason text] [--json]
   284→ * AC: @workflow-run-foundation ac-3, ac-5
   285→ */
   286→async function workflowAbort(
   287→  runRef: string,
   288→  options: { reason?: string; json?: boolean },
   289→) {
   290→  const ctx = await initContext();
   291→
   292→  const run = await findWorkflowRunByRef(ctx, runRef);
   293→  if (!run) {
   294→    error(errors.workflowRun.runNotFound(runRef));
   295→    process.exit(EXIT_CODES.NOT_FOUND);
   296→  }
   297→
   298→  // AC: @workflow-run-foundation ac-5 - Cannot abort completed or aborted runs
   299→  if (run.status === "completed") {
   300→    error(errors.workflowRun.cannotAbortCompleted);
   301→    process.exit(EXIT_CODES.VALIDATION_FAILED);
   302→  }
   303→
   304→  if (run.status === "aborted") {
   305→    error(errors.workflowRun.cannotAbortAborted);
   306→    process.exit(EXIT_CODES.VALIDATION_FAILED);
   307→  }
   308→
   309→  // Update run status
   310→  run.status = "aborted";
   311→  run.abort_reason = options.reason;
   312→  run.completed_at = new Date().toISOString();
   313→
   314→  await updateWorkflowRun(ctx, run);
   315→  await commitIfShadow(ctx.shadow, "workflow-abort");
   316→
   317→  if (isJsonMode()) {
   318→    output({ run_id: run._ulid, status: run.status });
   319→  } else {
   320→    success(`Aborted workflow run: ${shortUlid(run._ulid)}`);
   321→    if (options.reason) {
   322→      console.log(`  Reason: ${options.reason}`);
   323→    }
   324→  }
   325→}
   326→
   327→/**
   328→ * Command: kspec workflow pause @run-id [--json]
   329→ * AC: @workflow-advanced-features ac-1
   330→ */
   331→async function workflowPause(runRef: string, _options: { json?: boolean }) {
   332→  const ctx = await initContext();
   333→
   334→  const run = await findWorkflowRunByRef(ctx, runRef);
   335→  if (!run) {
   336→    error(errors.workflowRun.runNotFound(runRef));
   337→    process.exit(EXIT_CODES.NOT_FOUND);
   338→  }
   339→
   340→  // Only active runs can be paused
   341→  if (run.status !== "active") {
   342→    error(
   343→      `Cannot pause run ${shortUlid(run._ulid)}: current status is ${run.status}`,
   344→    );
   345→    process.exit(EXIT_CODES.VALIDATION_FAILED);
   346→  }
   347→
   348→  // Update run status
   349→  run.status = "paused";
   350→  run.paused_at = new Date().toISOString();
   351→
   352→  await updateWorkflowRun(ctx, run);
   353→  await commitIfShadow(ctx.shadow, "workflow-pause");
   354→
   355→  if (isJsonMode()) {
   356→    output({ run_id: run._ulid, status: run.status, paused_at: run.paused_at });
   357→  } else {
   358→    success(
   359→      `Paused run ${shortUlid(run._ulid)} at step ${run.current_step + 1}/${run.total_steps}`,
   360→    );
   361→  }
   362→}
   363→
   364→/**
   365→ * Command: kspec workflow resume @run-id [--json]
   366→ * AC: @workflow-advanced-features ac-2, ac-4
   367→ */
   368→async function workflowResume(runRef: string, _options: { json?: boolean }) {
   369→  const ctx = await initContext();
   370→  const metaCtx = await loadMetaContext(ctx);
   371→
   372→  const run = await findWorkflowRunByRef(ctx, runRef);
   373→  if (!run) {
   374→    error(errors.workflowRun.runNotFound(runRef));
   375→    process.exit(EXIT_CODES.NOT_FOUND);
   376→  }
   377→
   378→  // AC: @workflow-advanced-features ac-4 - Error if not paused
   379→  if (run.status !== "paused") {
   380→    error(
   381→      `Cannot resume run ${shortUlid(run._ulid)}: current status is ${run.status} (expected paused)`,
   382→    );
   383→    process.exit(EXIT_CODES.VALIDATION_FAILED);
   384→  }
   385→
   386→  // Update run status
   387→  run.status = "active";
   388→  run.paused_at = undefined;
   389→
   390→  await updateWorkflowRun(ctx, run);
   391→  await commitIfShadow(ctx.shadow, "workflow-resume");
   392→
   393→  // Get workflow definition to show current step
   394→  const workflow = metaCtx.workflows.find(
   395→    (w) => `@${w._ulid}` === run.workflow_ref,
   396→  );
   397→  if (!workflow) {
   398→    error(errors.workflowRun.workflowNotFound(run.workflow_ref));
   399→    process.exit(EXIT_CODES.NOT_FOUND);
   400→  }
   401→
   402→  const currentStep = workflow.steps[run.current_step];
   403→
   404→  if (isJsonMode()) {
   405→    output({
   406→      run_id: run._ulid,
   407→      status: run.status,
   408→      current_step: run.current_step,
   409→      total_steps: run.total_steps,
   410→      next_step: {
   411→        type: currentStep.type,
   412→        content: currentStep.content,
   413→      },
   414→    });
   415→  } else {
   416→    success(`Resumed run ${shortUlid(run._ulid)}`);
   417→    console.log(
   418→      `\nStep ${run.current_step + 1}/${run.total_steps}: [${currentStep.type}] ${currentStep.content}`,
   419→    );
   420→  }
   421→}
   422→
   423→/**
   424→ * Command: kspec workflow next [run-ref] [--skip] [--notes text] [--confirm] [--force] [--input key=value] [--json]
   425→ * AC: @workflow-step-navigation ac-1 through ac-6
   426→ * AC: @workflow-enforcement-modes ac-1 through ac-4
   427→ * AC: @workflow-advanced-features ac-3
   428→ */
   429→async function workflowNext(
   430→  runRef: string | undefined,
   431→  options: {
   432→    skip?: boolean;
   433→    notes?: string;
   434→    confirm?: boolean;
   435→    force?: boolean;
   436→    input?: string[];
   437→    json?: boolean;
   438→  },
   439→) {
   440→  const ctx = await initContext();
   441→  const metaCtx = await loadMetaContext(ctx);
   442→
   443→  let run: WorkflowRun | undefined;
   444→
   445→  // AC: @workflow-step-navigation ac-3, ac-4, ac-5
   446→  if (!runRef) {
   447→    const activeRuns = await findActiveRuns(ctx);
   448→
   449→    if (activeRuns.length === 0) {
   450→      // AC: @workflow-step-navigation ac-5
   451→      error(errors.workflowRun.noActiveRuns);
   452→      process.exit(EXIT_CODES.NOT_FOUND);
   453→    }
   454→
   455→    if (activeRuns.length > 1) {
   456→      // AC: @workflow-step-navigation ac-4
   457→      const runIds = activeRuns.map((r) => shortUlid(r._ulid));
   458→      error(errors.workflowRun.multipleActiveRuns(runIds));
   459→      process.exit(EXIT_CODES.VALIDATION_FAILED);
   460→    }
   461→
   462→    // AC: @workflow-step-navigation ac-3 - exactly one active run
   463→    run = activeRuns[0];
   464→  } else {
   465→    run = await findWorkflowRunByRef(ctx, runRef);
   466→    if (!run) {
   467→      error(errors.workflowRun.runNotFound(runRef));
   468→      process.exit(EXIT_CODES.NOT_FOUND);
   469→    }
   470→
   471→    if (run.status !== "active") {
   472→      error(errors.workflowRun.runNotActive(runRef, run.status));
   473→      process.exit(EXIT_CODES.VALIDATION_FAILED);
   474→    }
   475→  }
   476→
   477→  // Get workflow definition to access steps
   478→  const workflow = metaCtx.workflows.find(
   479→    (w) => `@${w._ulid}` === run.workflow_ref,
   480→  );
   481→  if (!workflow) {
   482→    error(errors.workflowRun.workflowNotFound(run.workflow_ref));
   483→    process.exit(EXIT_CODES.NOT_FOUND);
   484→  }
   485→
   486→  // Get current step and next step
   487→  const currentStepIndex = run.current_step;
   488→  const currentStep = workflow.steps[currentStepIndex];
   489→  const isStrictMode = workflow.enforcement === "strict";
   490→  const isLastStep = currentStepIndex === run.total_steps - 1;
   491→
   492→  // AC: @workflow-advanced-features ac-3 - Handle step inputs
   493→  const stepInputs: Record<string, string> = {};
   494→  if (currentStep.inputs && currentStep.inputs.length > 0) {
   495→    // Display required inputs if not in JSON mode
   496→    if (!isJsonMode()) {
   497→      console.log(
   498→        `Step ${currentStepIndex + 1}/${run.total_steps}: [${currentStep.type}] ${currentStep.content}`,
   499→      );
   500→      console.log(chalk.cyan("  Inputs required:"));
   501→      for (const input of currentStep.inputs) {
   502→        const requiredLabel = input.required !== false ? "" : " (optional)";
   503→        const typeLabel = input.type ? ` (${input.type})` : "";
   504→        const desc = input.description ? `: ${input.description}` : "";
   505→        console.log(
   506→          chalk.cyan(`    - ${input.name}${typeLabel}${requiredLabel}${desc}`),
   507→        );
   508→      }
   509→      console.log();
   510→    }
   511→
   512→    // Parse --input flags
   513→    if (options.input) {
   514→      for (const inputStr of options.input) {
   515→        const [key, ...valueParts] = inputStr.split("=");
   516→        if (!valueParts.length) {
   517→          error(
   518→            `Invalid input format: "${inputStr}". Expected format: key=value`,
   519→          );
   520→          process.exit(EXIT_CODES.VALIDATION_FAILED);
   521→        }
   522→        stepInputs[key] = valueParts.join("="); // Rejoin in case value contains '='
   523→      }
   524→    }
   525→
   526→    // Validate required inputs
   527→    for (const input of currentStep.inputs) {
   528→      if (input.required !== false && !stepInputs[input.name]) {
   529→        error(`Missing required input: ${input.name}`);
   530→        process.exit(EXIT_CODES.VALIDATION_FAILED);
   531→      }
   532→    }
   533→  }
   534→
   535→  // AC: @workflow-enforcement-modes ac-3 - Strict mode: --skip requires --force
   536→  if (options.skip && isStrictMode && !options.force) {
   537→    error(errors.workflowRun.skipRequiresForce);
   538→    process.exit(EXIT_CODES.VALIDATION_FAILED);
   539→  }
   540→
   541→  // AC: @workflow-enforcement-modes ac-2, ac-3 - Check exit criteria for CURRENT step
   542→  if (
   543→    currentStep.exit_criteria &&
   544→    currentStep.exit_criteria.length > 0 &&
   545→    !options.skip
   546→  ) {
   547→    // AC: @workflow-enforcement-modes ac-3 - Strict mode requires --confirm
   548→    if (isStrictMode && !options.confirm) {
